	//                 "tickSz": "0.0001",
	//                 "lotSz": "0.001",
	//                 "minSz": "0.5",
	//                 "ctType": "",
	//                 "alias": "",
	//                 "state": "live",
	//                 "maxLmtSz": "7692307",
	//                 "maxMktSz": "7692307"
	//             }
	//         ]
