func (this *Deepcoin) ParseTrade(trade any, optionalArgs ...any) any {
	//
	// public fetchTrades
	//
	//     {
	//         "instId": "ETH-USDT",
	//         "tradeId": "1001056388761321",
	//         "px": "4095.66",
	//         "sz": "0.01311251",
	//         "side": "sell",
	//         "ts": "1760367870000"
	//     }
	//
	// private fetchMyTrades
	//     {
	//         "instType": "SPOT",
	//         "instId": "ETH-USDT",
	//         "tradeId": "1001056429613610",
	//         "ordId": "1001435238208686",
	//         "clOrdId": "",
	//         "billId": "10010564296136101",
	//         "tag": "",
	//         "fillPx": "3791.15",
	//         "fillSz": "0.004",
	//         "side": "sell",
	//         "posSide": "",
	//         "execType": "",
	//         "feeCcy": "USDT",
	//         "fee": "0.0151646",
	//         "ts": "1760704540000"
	//     }
	//
	market := GetArg(optionalArgs, 0, nil)
	_ = market
	var marketId any = this.SafeString(trade, "instId")
	market = this.SafeMarket(marketId, market)
	var timestamp any = this.SafeInteger(trade, "ts")
	var side any = this.SafeString(trade, "side")
	var execType any = this.SafeString(trade, "execType")
	var fee any = nil
	var feeCost any = this.SafeString(trade, "fee")
	if IsTrue(!IsEqual(feeCost, nil)) {
		var feeCurrencyId any = this.SafeString(trade, "feeCcy")
		var feeCurrencyCode any = this.SafeCurrencyCode(feeCurrencyId)
		fee = map[string]any{
			"cost":     feeCost,
			"currency": feeCurrencyCode,
		}
	}
	return this.SafeTrade(map[string]any{
		"info":         trade,
		"timestamp":    timestamp,
		"datetime":     this.Iso8601(timestamp),
		"symbol":       GetValue(market, "symbol"),
		"id":           this.SafeString(trade, "tradeId"),
		"order":        this.SafeString(trade, "ordId"),
		"type":         nil,
		"takerOrMaker": this.ParseTakerOrMaker(execType),
		"side":         side,
		"price":        this.SafeString2(trade, "fillPx", "px"),
		"amount":       this.SafeString2(trade, "fillSz", "sz"),
		"cost":         nil,
		"fee":          fee,
	}, market)
}
